-- 071: Data fix — PO-55UKXR2 order-plan lines were wrong (carried extra SKUs not on the actual Cin7 PO).
-- Corrected against the Cin7 export of 26-06-2026: the real PO has 48 lines. Ben applied this to his sandbox
-- (96 -> 48, verified to match the ERP mirror exactly). This migration makes prod match regardless of its
-- current state: it UPSERTS the 48 correct lines, then DELETES any other PO-55UKXR2 line. Idempotent.
-- NOTE: cost_price values are the planner's existing costs (carried from sandbox); leave as-is.

ON CONFLICT (po_sku) DO UPDATE SET qty = excluded.qty, cost_price = excluded.cost_price,
  carton_qty = excluded.carton_qty, po_status = excluded.po_status, updated_at = now();

DELETE FROM planner.purchase_order_lines
WHERE po = 'PO-55UKXR2' AND sku NOT IN ('HAIRW-SUE-IBZAGLW', 'HAIRW-SUE-MIAMI', 'HAIRW-SUE-OCETRES', 'HAIRW-WAF-CHRYBMB', 'HAIRW-WAF-TIGPALM', 'PICNIC-DES-XL-STRIPLIFE', 'PONCHK-CAB-MD-BLUE-NS', 'PONCHK-CAB-SM-BLUE-NS', 'PONCHK-CAB-SM-NAVY-NS', 'PONCHK-KID-MD-CHECKOUT', 'PONCHK-KID-MD-INTOWILD', 'PONCHK-KID-SM-CHECKOUT', 'PONCHK-KID-SM-INTOWILD', 'PONCHK-SUM-MD-CSTCANDY', 'TEATWL-MD-BAKEME', 'TEATWL-MD-BIGDILL', 'TEATWL-MD-CTCHDAY', 'TEATWL-MD-KISSCOOK', 'TEATWL-MD-MTCHCRSH', 'TEATWL-MD-ROOTING', 'TEATWL-MD-SHRIMP', 'TEATWL-MD-STRWPOP', 'TEATWL-MD-XTRSAUC', 'TOWLB-DES-LG-BLUSKY', 'TOWLB-DES-LG-GRECSHR', 'TOWLB-DES-LG-MELLOW', 'TOWLB-DES-LG-PNKPARA', 'TOWLB-DES-LG-PSTPIER', 'TOWLB-DES-LG-RSPROAD', 'TOWLB-DES-LG-WTRSUG', 'TOWLB-DES-XL-BLUSKY', 'TOWLB-DES-XL-GRECSHR', 'TOWLB-DES-XL-MELLOW', 'TOWLB-DES-XL-PNKPARA', 'TOWLB-DES-XL-PSTPIER', 'TOWLB-DES-XL-RSPROAD', 'TOWLB-DES-XL-WTRSUG', 'TOWLB-SUM-LG-CSTCANDY', 'TOWLB-SUM-LG-MIAMI', 'TOWLB-SUM-XL-COLAGN', 'TOWLB-SUM-XL-CSTCANDY', 'TOWLB-SUM-XL-MIAMI', 'TOWLF-ESS-LG-DKBLU', 'TOWLF-ESS-LG-GREEN-R', 'TOWLF-ESS-LG-PINK-R', 'TOWLF-ESS-XL-PINK-R', 'TOWLH-CLB-LG-PEPPNCH', 'TOWLH-CLB-XL-CHRYBMB');
